	public function path_create( $request ) { $p=(array)$request->get_json_params();$rate=RSV_Security::rate_limit('future30_learning_paths',30,HOUR_IN_SECONDS);if(is_wp_error($rate))return $rate;$idem=$request->get_header('Idempotency-Key');$begin=RSV_Security::idempotency_begin('future30_learning_path',$idem,$p);if(is_wp_error($begin))return $begin;if(!empty($begin['replay']))return rest_ensure_response($begin['response']);$refs=array_values(array_unique(array_map('sanitize_text_field',(array)($p['file05_course_refs']??array()))));foreach($refs as $ref)if(true!==apply_filters('rsv_future30_file05_public_ref_valid',false,$ref)){RSV_Security::idempotency_fail('future30_learning_path',$idem);return RSV_Helpers::error('rsv_learning_ref_invalid',__('Every learning reference must be current and public according to File 05.',RSV_TEXT_DOMAIN),422);}$steps=array_slice((array)($p['steps']??array()),0,100);return self::idempotent_finish_result('future30_learning_path',$idem,self::put_object('F11-FUT-002','learning_path',0,$p['title']??'',array('level'=>RSV_Helpers::enum($p['level']??'beginner',array('beginner','intermediate','advanced'),'beginner'),'description'=>$p['description']??'','steps'=>$steps,'file05_course_refs'=>$refs),$p['public_id']??'')); }

	public function reel_feature_get( $request ) {
		list($fid,$def)=self::feature($request['feature']); if(!$fid)return RSV_Helpers::error('rsv_future_unknown',__('Unknown future feature.',RSV_TEXT_DOMAIN),404);if(!self::generic_public_allowed($fid))return RSV_Helpers::error('rsv_future_private',__('This capability is private and available only through its dedicated endpoint.',RSV_TEXT_DOMAIN),404);$reel=self::reel($request['id']);if(is_wp_error($reel))return $reel;
		$public=RSV_Security::can_view_reel($reel); if(!$public)return RSV_Helpers::error('rsv_not_found',__('Reel not found.',RSV_TEXT_DOMAIN),404);
		$projection=self::public_projection($fid,$reel);return rest_ensure_response(array('feature_id'=>$fid,'definition'=>$def,'objects'=>$projection['objects'],'edges'=>$projection['edges']));
	}

	public function reel_feature_write( $request ) {
		list( $fid, $def ) = self::feature( $request['feature'] );
		if ( ! $fid ) return RSV_Helpers::error( 'rsv_future_unknown', __( 'Unknown future feature.', RSV_TEXT_DOMAIN ), 404 );
		if ( ! self::generic_write_allowed( $fid ) ) return RSV_Helpers::error( 'rsv_future_dedicated_endpoint', __( 'Use the dedicated protected endpoint for this capability.', RSV_TEXT_DOMAIN ), 400 );
		$reel = self::reel( $request['id'], true );
		if ( is_wp_error( $reel ) ) return $reel;
		$rate = RSV_Security::rate_limit( 'future30_mutation', 120, HOUR_IN_SECONDS );
		if ( is_wp_error( $rate ) ) return $rate;
		$p     = (array) $request->get_json_params();
		$idem  = $request->get_header( 'Idempotency-Key' );
		$scope = 'future30_' . strtolower( str_replace( '-', '_', $fid ) );
		$begin = RSV_Security::idempotency_begin( $scope, $idem, $p );
		if ( is_wp_error( $begin ) ) return $begin;
		if ( ! empty( $begin['replay'] ) ) return rest_ensure_response( $begin['response'] );

		$response = RSV_DB::transaction(
			static function () use ( $fid, $def, $reel, $p, $scope, $idem ) {
				$result = self::feature_write( $fid, $reel, $p );
				if ( is_wp_error( $result ) ) return $result;
				$payload = array( 'ok' => true, 'feature_id' => $fid, 'result' => $result );
				if ( ! RSV_Security::idempotency_finish( $scope, $idem, $payload )
					|| ! RSV_Helpers::audit( 'reel', $reel['id'], 'future30_write', '', '', $fid, array( 'feature' => $def['slug'] ) )
					|| ! RSV_Helpers::outbox( 'ReelFutureCapabilityUpdated', 'reel', $reel['id'], array( 'reel_public_id' => $reel['public_id'], 'feature_id' => $fid ) ) ) {
					return RSV_Helpers::error( 'rsv_future30_evidence_failed', __( 'The Future30 change could not be committed with complete replay, audit and event evidence.', RSV_TEXT_DOMAIN ), 500 );
				}
				return $payload;
			}
		);
		if ( is_wp_error( $response ) ) {
			RSV_Security::idempotency_fail( $scope, $idem );
			return $response;
		}
		return rest_ensure_response( $response );
	}

